from pathlib import Path
import xml.etree.ElementTree as ET
from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet,ParagraphStyle
from reportlab.lib.units import mm
from reportlab.platypus import SimpleDocTemplate,Paragraph,Spacer,Table,TableStyle,PageBreak

ROOT=Path(__file__).resolve().parents[1];JUNIT=ROOT/'test-results'/'junit.xml';OUT=ROOT/'output'/'pdf'/'SBB-Oxygen-House-Admin-Reviews-Test-Report.pdf'
if not JUNIT.exists():raise SystemExit('Run npm run test:reviews:all first.')
rows=[]
for suite in ET.parse(JUNIT).getroot().findall('testsuite'):
 for case in suite.findall('testcase'):
  name=case.get('name','')
  if 'REV-MATRIX-' not in name:continue
  failure=case.find('failure');result='FAILED'if failure is not None else('SKIPPED'if case.find('skipped')is not None else'PASSED')
  finding='Verified'
  if failure is not None:finding='Search does not filter unrelated rows.'if 'REV-MATRIX-F-001'in name else'Action icon button has no accessible name.'
  rows.append([name.split('>')[-1].strip(),suite.get('hostname','Unknown'),result,f"{float(case.get('time',0)):.1f}s",finding])
if not rows:raise SystemExit('No Reviews matrix results found.')
p=sum(r[2]=='PASSED'for r in rows);f=sum(r[2]=='FAILED'for r in rows);sk=sum(r[2]=='SKIPPED'for r in rows)
OUT.parent.mkdir(parents=True,exist_ok=True);styles=getSampleStyleSheet();navy=colors.HexColor('#102331');teal=colors.HexColor('#0B6980');line=colors.HexColor('#B9C9D1');green=colors.HexColor('#DDF4E6');red=colors.HexColor('#FADADA');amber=colors.HexColor('#FFF0C2')
title=ParagraphStyle('Title',parent=styles['Title'],fontSize=20,leading=24,textColor=navy,spaceAfter=3*mm);h=ParagraphStyle('H',parent=styles['Heading1'],fontSize=13,leading=16,textColor=teal,spaceBefore=3*mm,spaceAfter=2*mm);body=ParagraphStyle('Body',parent=styles['BodyText'],fontSize=8.5,leading=12,textColor=navy);small=ParagraphStyle('Small',parent=body,fontSize=7,leading=9);tiny=ParagraphStyle('Tiny',parent=body,fontSize=5.8,leading=6.7)
def footer(canvas,doc):
 canvas.saveState();canvas.setStrokeColor(line);canvas.line(14*mm,12*mm,196*mm,12*mm);canvas.setFillColor(colors.HexColor('#607783'));canvas.setFont('Helvetica',6.5);canvas.drawString(14*mm,8*mm,'SBB Oxygen House - Admin Reviews Test Report');canvas.drawRightString(196*mm,8*mm,f'Page {doc.page}');canvas.restoreState()
doc=SimpleDocTemplate(str(OUT),pagesize=A4,leftMargin=14*mm,rightMargin=14*mm,topMargin=14*mm,bottomMargin=17*mm,title='Admin Reviews Test Report',author='Calibur Automation')
story=[Paragraph('SBB OXYGEN HOUSE',ParagraphStyle('Brand',parent=small,textColor=teal,fontSize=10,leading=12)),Paragraph('ADMIN REVIEWS TEST REPORT',title),Paragraph('Functional, UI, nonfunctional and web/mobile browser compatibility evidence',body),Spacer(1,5*mm)]
summary=Table([['Target','Matrix','Passed','Failed','Skipped'],['/admin/reviews',len(rows),p,f,sk]],colWidths=[72*mm,27*mm,27*mm,27*mm,27*mm]);summary.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),teal),('TEXTCOLOR',(0,0),(-1,0),colors.white),('ALIGN',(1,0),(-1,-1),'CENTER'),('GRID',(0,0),(-1,-1),.4,line),('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),('FONTSIZE',(0,0),(-1,-1),8),('PADDING',(0,0),(-1,-1),6)]));story +=[summary,Spacer(1,5*mm),Paragraph('Executive result',h),Paragraph(f'The eight-profile compatibility matrix completed with <b>{p} passed, {f} failed and {sk} skipped</b>. Responsive UI fit passed in every profile. Search functionality and accessible naming of review action buttons failed consistently across desktop and mobile engines.',body),Paragraph('Confirmed application findings',h)]
findings=[['Severity','Area','Finding and expected correction'],['High','Reviews search','Entering an existing reviewer name leaves unrelated rows visible. Connect the search input to the review dataset and verify product, reviewer and review-text matching.'],['Critical','Action accessibility','The hide/approve icon button has no accessible name (Axe button-name). Add a stable aria-label such as Hide review or Approve review.']]
ft=Table([[Paragraph(str(c),small)for c in row]for row in findings],colWidths=[25*mm,42*mm,113*mm]);ft.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),navy),('TEXTCOLOR',(0,0),(-1,0),colors.white),('BACKGROUND',(0,1),(0,-1),amber),('GRID',(0,0),(-1,-1),.4,line),('VALIGN',(0,0),(-1,-1),'TOP'),('PADDING',(0,0),(-1,-1),5)]));story +=[ft,Spacer(1,4*mm),Paragraph('Data and mutation safety',h),Paragraph('The Reviews admin page has no create form, so it cannot generate isolated review test data. Read-only checks use current rows. The status mutation test identifies one exact row, changes Approved/Pending once, verifies the result, and immediately restores the original status in a guarded finally block. Bulk approve/hide buttons are verified without activation. Delete confirmation is opened and cancelled only; no review is deleted.',body)]
story +=[PageBreak(),Paragraph('Detailed coverage',title)]
coverage=[('Page and table','Heading, guidance text, Product/Reviewer/Rating/Review/Status/Date/Actions columns and live rows.'),('Search','Existing reviewer and no-match values; unrelated rows must disappear. The live page currently fails this check.'),('Status filter','All status, Pending and Approved options are present and keyboard dismissible.'),('Selection and bulk actions','Checkbox selection count, Approve Selected, Hide Selected and Clear; Clear removes selection without mutation.'),('Row status lifecycle','Hide/approve action, success feedback, status transition and restoration to the original state.'),('Delete safety','Delete Review dialog and Cancel behavior; production deletion is never confirmed.'),('UI and responsive','Control visibility, full combobox sizing, keyboard focus and document-width overflow.'),('Accessibility','Axe WCAG scan of listing and delete dialog; unnamed action button is reported as critical.'),('Performance','Authenticated page readiness under 10 seconds.'),('Security and quality','HTTPS, exact authenticated route, no login redirect, uncaught JavaScript errors and HTTP 5xx monitoring.'),('Compatibility','Chrome, Edge, Firefox and Safari-compatible web/mobile profiles: 8 profiles x 3 checks = 24.')]
ct=Table([['Testing area','What was verified']]+[[Paragraph(a,small),Paragraph(b,small)]for a,b in coverage],colWidths=[43*mm,137*mm],repeatRows=1);ct.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),teal),('TEXTCOLOR',(0,0),(-1,0),colors.white),('GRID',(0,0),(-1,-1),.35,line),('VALIGN',(0,0),(-1,-1),'TOP'),('PADDING',(0,0),(-1,-1),4)]));story +=[ct,Spacer(1,4*mm),Paragraph('Browser interpretation',h),Paragraph('Chrome and Edge profiles use installed vendor browsers. Firefox uses Playwright Firefox. Safari-compatible profiles use Playwright WebKit on Windows and indicate engine-level compatibility, not physical Apple Safari certification.',body),Paragraph('Conclusion',h),Paragraph('Status changes, selection controls, delete cancellation, layout, performance, HTTPS and runtime quality are operational. Release acceptance should remain conditional on fixing Reviews search and adding accessible names to row action buttons.',body)]
story +=[PageBreak(),Paragraph('Compatibility matrix results',title),Paragraph('Each row is from the latest JUnit execution generated by npm run test:reviews:all.',body),Spacer(1,3*mm)]
data=[['Test case','Profile','Result','Time','Finding']]+[[Paragraph(r[0],tiny),Paragraph(r[1],tiny),Paragraph(r[2],tiny),Paragraph(r[3],tiny),Paragraph(r[4],tiny)]for r in rows];dt=Table(data,colWidths=[77*mm,34*mm,20*mm,15*mm,34*mm],repeatRows=1);cmd=[('BACKGROUND',(0,0),(-1,0),teal),('TEXTCOLOR',(0,0),(-1,0),colors.white),('GRID',(0,0),(-1,-1),.3,line),('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),3),('RIGHTPADDING',(0,0),(-1,-1),3),('TOPPADDING',(0,0),(-1,-1),2),('BOTTOMPADDING',(0,0),(-1,-1),2)]
for i,r in enumerate(rows,1):cmd.append(('BACKGROUND',(2,i),(2,i),green if r[2]=='PASSED'else red if r[2]=='FAILED'else amber))
dt.setStyle(TableStyle(cmd));story.append(dt);doc.build(story,onFirstPage=footer,onLaterPages=footer);print(OUT)
